mapper.select:
    select h.REQ_NUMBER from csh_deposit_deduct_req_hd h,csh_deposit_deduct_req_ln l
	where h.req_hd_id = l.req_hd_id
	  and l.source_info_id = #{sourceInfoId}
	  and h.req_status = 'APPROVED'
	  and nvl(h.deduct_status,'BACK') = 'SUCCESS'
	  and h.req_hd_id != #{reqHdId}
	  and l.info_id_batch = #{infoIdBatch}

